import sys
from pathlib import Path

import pytest

from qualityintel.ingest.junit import parse_junit

sys.path.insert(0, str(Path(__file__).parents[3] / "tools"))
from sanitize_junit import main, sanitize

pytestmark = pytest.mark.unit

ORIGINAL = b"""<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by a test reporter -->
<testsuite name="TestSuite" hostname="build-agent-7" timestamp="2026-10-13T09:10:00 UTC">
  <properties>
    <property name="user.home" value="/home/someone"/>
    <property name="java.class.path" value="/opt/app/lib/secret.jar"/>
    <property name="browser" value="firefox"/>
  </properties>
  <testcase classname="com.example.LoginTest" name="logsIn" time="1.5">
    <system-out>token=abc123</system-out>
  </testcase>
  <testcase classname="com.example.LoginTest" name="rejectsBadPassword" time="2.25">
    <failure message="expected 401" type="AssertionError">at LoginTest.java:42</failure>
    <system-err>password=hunter2</system-err>
  </testcase>
</testsuite>
"""


def test_private_data_is_removed() -> None:
    """Logs, JVM properties, host names and comments do not survive."""
    cleaned = sanitize(ORIGINAL)

    for secret in (
        b"/home/someone",
        b"secret.jar",
        b"build-agent-7",
        b"token=abc123",
        b"hunter2",
        b"Generated by",
    ):
        assert secret not in cleaned


def test_the_copy_imports_to_the_same_results() -> None:
    """Names, outcomes, durations, failures, timestamps and allowed context are unchanged."""
    before = parse_junit(ORIGINAL, source="x.xml").run
    after = parse_junit(sanitize(ORIGINAL), source="x.xml").run

    assert after.results == before.results
    assert after.context == before.context
    assert after.started_at == before.started_at


def test_command_line_writes_the_sanitised_file(tmp_path: Path) -> None:
    """`python tools/sanitize_junit.py in out` creates the output directory and file."""
    source = tmp_path / "in.xml"
    source.write_bytes(ORIGINAL)
    target = tmp_path / "out" / "clean.xml"

    assert main([str(source), str(target), "--set", "build=abc"]) == 0
    assert b"hunter2" not in target.read_bytes()


def test_command_line_needs_two_arguments(capsys: pytest.CaptureFixture[str]) -> None:
    """Wrong usage prints the usage line and returns 2."""
    assert main(["only-one.xml"]) == 2
    assert "usage:" in capsys.readouterr().err


def test_context_is_recorded_on_every_top_level_suite() -> None:
    """--set values become properties the importer reads as run context."""
    two_suites = b'<testsuites><testsuite name="a"><testcase name="t"/></testsuite><testsuite name="b"><testcase name="u"/></testsuite></testsuites>'

    cleaned = sanitize(two_suites, {"build": "1d03232", "framework": "pytest"})
    run = parse_junit(cleaned, source="x.xml").run

    assert run.context.build == "1d03232"
    assert run.context.framework == "pytest"
    assert cleaned.count(b'name="build"') == 2


def test_recorded_context_replaces_an_existing_value() -> None:
    """A property already in the file is replaced, not duplicated."""
    cleaned = sanitize(ORIGINAL, {"browser": "chrome"})

    assert cleaned.count(b'name="browser"') == 1
    assert parse_junit(cleaned, source="x.xml").run.context.browser == "chrome"


def test_only_context_names_can_be_recorded() -> None:
    """Arbitrary properties cannot be smuggled into a sample."""
    with pytest.raises(ValueError, match="not a context property: owner"):
        sanitize(ORIGINAL, {"owner": "someone"})


def test_command_line_rejects_set_without_a_value(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    """--set needs NAME=VALUE."""
    source = tmp_path / "in.xml"
    source.write_bytes(ORIGINAL)

    assert main([str(source), str(tmp_path / "out.xml"), "--set", "build"]) == 2
    assert "--set needs NAME=VALUE" in capsys.readouterr().err


def test_timestamp_fills_only_missing_suite_timestamps() -> None:
    """Surefire files get a start time; a producer's own timestamp is never overwritten."""
    surefire = b'<testsuite name="TestSuite"><testcase name="t"/></testsuite>'

    filled = parse_junit(sanitize(surefire, timestamp="2026-10-13T09:00:00Z"), source="x.xml").run
    kept = parse_junit(sanitize(ORIGINAL, timestamp="2030-01-01T00:00:00Z"), source="x.xml").run

    assert filled.started_at is not None
    assert filled.started_at.isoformat() == "2026-10-13T09:00:00+00:00"
    assert kept.started_at is not None
    assert kept.started_at.year == 2026


def test_overwrite_timestamp_replaces_merge_time_on_all_suites() -> None:
    """Merged Playwright reports carry the merge time; the run's start time replaces it."""
    merged = b'<testsuites><testsuite name="a" timestamp="2030-01-01T00:00:00Z"><testsuite name="b" timestamp="2030-01-01T00:00:00Z"><testcase name="t"/></testsuite></testsuite></testsuites>'

    cleaned = sanitize(merged, timestamp="2026-10-19T09:15:00Z", overwrite_timestamp=True)

    assert b"2030" not in cleaned
    assert cleaned.count(b'timestamp="2026-10-19T09:15:00Z"') == 2
